
import subprocess,json,base64,os,shutil,sqlite3,hashlib,datetime,time,io,types,sys,unittest,importlib.util
from pathlib import Path
payload={'plan': '', 'tests': ''}
release=Path(subprocess.check_output(['systemctl','show','gongwei-leader','-p','WorkingDirectory','--value'],text=True).strip()).resolve()
assert release==Path('/opt/gongwei/releases/20261007-120338-maintenance')
backup=Path('/opt/gongwei/backups')/('20261008-footer-fix-'+datetime.datetime.now().strftime('%H%M%S'));backup.mkdir(mode=0o700)
original=release/'plan_continuation.py';shutil.copy2(original,backup/'plan_continuation-before.py');new=backup/'plan_continuation-next.py';new.write_bytes(base64.b64decode(payload['plan']));testpath=backup/'test_homepage_continuation.py';testpath.write_bytes(base64.b64decode(payload['tests']))
roles=['web','resource','workorder','audio','leader','resource-inbox','workorder-inbox','amp-heartbeat']
def services():return {r:dict(x.split('=',1) for x in subprocess.check_output(['systemctl','show','gongwei-'+r,'-p','ActiveState','-p','MainPID','-p','UnitFileState'],text=True).splitlines()) for r in roles}
r={'backup':str(backup),'release':str(release),'before':services(),'old_sha256':hashlib.sha256(original.read_bytes()).hexdigest(),'new_sha256':hashlib.sha256(new.read_bytes()).hexdigest(),'changed_files':['plan_continuation.py'],'platform_verified':False}
os.chdir(release);sys.path.insert(0,str(release))
spec=importlib.util.spec_from_file_location('plan_continuation',new);module=importlib.util.module_from_spec(spec);sys.modules['plan_continuation']=module;spec.loader.exec_module(module)
spec=importlib.util.spec_from_file_location('footer_fix_tests',testpath);tests=importlib.util.module_from_spec(spec);spec.loader.exec_module(tests);stream=io.StringIO();result=unittest.TextTestRunner(stream=stream,verbosity=2).run(unittest.defaultTestLoader.loadTestsFromModule(tests));r['tests']={'run':result.testsRun,'errors':len(result.errors),'failures':len(result.failures),'pass':result.wasSuccessful(),'output':stream.getvalue()}
if not result.wasSuccessful():r['pass_result']=False;print(json.dumps(r));sys.exit(0)
with sqlite3.connect('file:/var/lib/gongwei-leader/rpc.sqlite3?mode=ro',uri=True) as db:assert db.execute('SELECT count(*) FROM rpc_tasks WHERE pending_json IS NOT NULL OR cancel_json IS NOT NULL').fetchone()[0]==0,'Leader still has pending work'
for name,path in [('business','/opt/gongwei/shared/data/stage2.db'),('rpc','/var/lib/gongwei-leader/rpc.sqlite3')]:
 with sqlite3.connect('file:'+path+'?mode=ro',uri=True) as src,sqlite3.connect(backup/(name+'.sqlite3')) as dest:src.backup(dest)
 os.chmod(backup/(name+'.sqlite3'),0o600)
try:
 st=original.stat();tmp=original.with_suffix('.py.final-flow-tmp');tmp.write_bytes(new.read_bytes());os.chmod(tmp,st.st_mode&0o777);os.chown(tmp,st.st_uid,st.st_gid);tmp.replace(original)
 subprocess.run(['systemctl','restart','gongwei-leader'],check=True,timeout=50)
 for _ in range(40):
  if subprocess.check_output(['systemctl','is-active','gongwei-leader'],text=True).strip()=='active' and subprocess.run(['ss','-ltnH','sport = :18443'],capture_output=True,text=True).stdout.strip():break
  time.sleep(.25)
 else:raise RuntimeError('Leader listener not ready')
 r['after']=services();assert all(v['ActiveState']=='active' for v in r['after'].values());assert all(r['after'][role]['MainPID']==r['before'][role]['MainPID'] for role in roles if role!='leader')
 r['pass_result']=True
except Exception as e:
 shutil.copy2(backup/'plan_continuation-before.py',original);subprocess.run(['systemctl','restart','gongwei-leader'],check=True,timeout=50);r.update(pass_result=False,rolled_back=True,error=type(e).__name__+': '+str(e),after=services())
print(json.dumps(r,ensure_ascii=False,indent=2))
